steps.script:
### MiMa: An S-Plus/R function to fit meta-analytic mixed-, random-, and fixed-effects models ### author: Wolfgang Viechtbauer (University of Maastricht) ### e-mail: wvb (at) wvbauer dot com ### http://www.wvbauer.com/ ### comments, feedback, questions, and suggestions for improvements all welcome ### please read the tutorial first before using this function ### current version: 1.4
mima <- function(yi, vi, mods, method="REML", threshold=0.00001, maxiter=100, alpha=0.05, digits=4, fe="no", verbose="no", out="no") {
k <- length(yi) intrcpt <- rep(1,k) X <- cbind(intrcpt, mods) y <- as.matrix(yi) p <- dim(X)[2] - 1 ### number of moderators in the model
### function to obtain the trace of a matrix tr <- function(X) { sum(diag(X)) }
if (fe == "no") {
if (method == "HE") { M <- X %*% solve(t(X) %*% X) %*% t(X) RSS <- t(y) %*% ( diag(k) - M ) %*% y vart <- ( RSS - tr( (diag(k)-M) %*% diag(vi) ) ) / ( k-p-1 ) }
if (method == "DL") { wi <- 1/vi W <- diag(wi) b <- solve(t(X) %*% W %*% X) %*% t(X) %*% W %*% y RSS <- t(y - X %*% b) %*% W %*% (y - X %*% b) vart <- ( RSS - (k-p-1) ) / ( sum(wi) - tr( t(X) %*% W %*% W %*% X %*% solve( t(X) %*% W %*% X ) ) ) }
if (method == "SH") { vart0 <- sum( (yi - mean(yi))^2 ) / k wi <- 1/(vi + vart0) W <- diag(wi) P <- W - W %*% X %*% solve(t(X) %*% W %*% X) %*% t(X) %*% W vart <- (vart0/(k-p-1)) * t(y)%*%P%*%y }
conv <- 1 itprec <- threshold change <- 1 iter <- 0
if (method == "REML" || method == "ML" || method == "EB") {
vart <- var(yi) - 1/k*sum(vi) ### initial estimate = HE estimator in RE model vart[vart < 0] <- 0 ### set to zero in case the initial estimate is negative
while (change > itprec) { if(verbose == "yes") cat("Iteration:", iter, " Estimate of (Residual) Heterogeneity:", round(vart, 8), "\n") iter <- iter + 1 varm <- vart wi <- 1/(vi + vart) W <- diag(wi) V <- diag(vi) P <- W - W %*% X %*% solve(t(X) %*% W %*% X) %*% t(X) %*% W if (method == "REML") { adj <- solve( tr(P%*%P) ) %*% ( t(y)%*%P%*%P%*%y - tr(P) ) } if (method == "ML") { adj <- solve( tr(W%*%W) ) %*% ( t(y)%*%P%*%P%*%y - tr(W) ) } if (method == "EB") { adj <- solve( tr(W) ) %*% ( (k/(k-p-1)) %*% t(y)%*%P%*%y - k ) } while (vart + adj < 0) { adj <- adj / 2 } vart <- vart + adj change <- abs(varm - vart) if (iter > maxiter) { conv <- 0 break } } }
if (conv == 0) { cat("Fisher scoring algorithm did not converge\nTry increasing maxiter or use a different estimation method\n") break }
}
if (fe == "yes") vart <- 0
wi <- 1/vi W <- diag(wi) b <- solve(t(X) %*% W %*% X) %*% t(X) %*% W %*% y vb <- solve(t(X) %*% W %*% X) QE <- sum(wi * yi^2) - t(b) %*% solve(vb) %*% b QEp <- 1-pchisq(QE, df=k-p-1)
vart[vart < 0] <- 0 wi <- 1/(vi + vart) W <- diag(wi) b <- solve(t(X) %*% W %*% X) %*% t(X) %*% W %*% y vb <- solve(t(X) %*% W %*% X)
if (p > 0) { QME <- t(b)[2:(p+1)] %*% solve(vb[2:(p+1),2:(p+1)]) %*% b[2:(p+1)] QMEp <- 1 - pchisq(QME, df=p) } else { QME <- NA QMEp <- NA }
zvals <- b/sqrt(diag(vb)) zp <- 2*(1-pnorm(abs(zvals))) lbsci <- b - qnorm(1-alpha/2) * sqrt(diag(vb)) ubsci <- b + qnorm(1-alpha/2) * sqrt(diag(vb))
if (out == "yes") { outlist <- list(vart, b, vb) names(outlist) <- c("vart", "b", "vb") outlist } else {
cat("\n") cat("Estimate of (Residual) Heterogeneity:", round(vart,digits)) cat("\n\n")
cat("Test for (Residual) Heterogeneity:") cat("\n\n") cat("QE = ", round(QE,digits)) cat("\n") cat("df = ", k-p-1) cat("\n") cat("p-value = ", round(QEp,digits)) cat("\n\n")
cat("Parameter Estimates:") cat("\n\n") print(round(b,digits)) cat("\n")
cat("Variance-Covariance Matrix of Parameter Estimates:") cat("\n\n") print(round(vb,digits)) cat("\n")
cat("Omnibus Test of all Moderators:") cat("\n\n") cat("QME = ", round(QME,digits)) cat("\n") cat("df = ", p) cat("\n") cat("p-value = ", round(QMEp,digits)) cat("\n\n")
cat("Individual Moderator Tests:") cat("\n\n") ztest <- cbind(b, sqrt(diag(vb)), zvals, zp, lbsci, ubsci) ztest <- data.frame(ztest) names(ztest) <- c("estimate", "SE", "zval", "pval", "CI_L", "CI_U") print(round(ztest,digits)) cat("\n")
} }
mods <- data.matrix(mods) capture.output(mima(yiVAR0, viVAR0, mods))
